import React, { useRef, useEffect } from 'react';
import {
  ChatEntry,
  ChatToggle,
  useChat,
  useMaybeLayoutContext,
} from '@livekit/components-react';
import Icon from '../AppIcon';
import { useToast } from '../../contexts/ToastContext';
import { detectContactSharing, CONTACT_GUARD_SHORT } from '../../utils/contactGuard';

/**
 * LiveKit chat UI with LUC contact-sharing guard.
 * Drop-in replacement for the default LiveKit Chat component.
 */
const ModeratedLiveChat = (props) => {
  const ulRef = useRef(null);
  const inputRef = useRef(null);
  const { addToast } = useToast();
  const { chatMessages, send, isSending } = useChat();
  const layoutContext = useMaybeLayoutContext();
  const lastReadMsgAt = useRef(0);

  const handleSubmit = async (event) => {
    event.preventDefault();
    const value = inputRef.current?.value?.trim();
    if (!value) return;

    const guard = detectContactSharing(value);
    if (guard.blocked) {
      addToast(CONTACT_GUARD_SHORT, 'error');
      return;
    }

    await send(value);
    if (inputRef.current) {
      inputRef.current.value = '';
      inputRef.current.focus();
    }
  };

  useEffect(() => {
    ulRef.current?.scrollTo({ top: ulRef.current.scrollHeight });
  }, [chatMessages]);

  useEffect(() => {
    if (!layoutContext || chatMessages.length === 0) return;

    if (
      layoutContext.widget.state?.showChat &&
      chatMessages.length > 0 &&
      lastReadMsgAt.current !== chatMessages[chatMessages.length - 1]?.timestamp
    ) {
      lastReadMsgAt.current = chatMessages[chatMessages.length - 1]?.timestamp;
      return;
    }

    const unreadMessageCount = chatMessages.filter(
      (msg) => !lastReadMsgAt.current || msg.timestamp > lastReadMsgAt.current
    ).length;

    const { widget } = layoutContext;
    if (unreadMessageCount > 0 && widget.state?.unreadMessages !== unreadMessageCount) {
      widget.dispatch?.({ msg: 'unread_msg', count: unreadMessageCount });
    }
  }, [chatMessages, layoutContext]);

  return (
    <div {...props} className="lk-chat">
      <div className="lk-chat-header">
        <div className="flex flex-col gap-0.5 min-w-0">
          <span>Messages</span>
          <span className="text-[9px] font-medium opacity-70 normal-case tracking-normal truncate">
            No phones, emails, or WhatsApp — stay on LUC
          </span>
        </div>
        {layoutContext && (
          <ChatToggle className="lk-close-button">
            <Icon name="X" size={16} />
          </ChatToggle>
        )}
      </div>

      <ul className="lk-list lk-chat-messages" ref={ulRef}>
        {chatMessages.map((msg, idx, allMsg) => {
          const hideName = idx >= 1 && allMsg[idx - 1].from === msg.from;
          const hideTimestamp = idx >= 1 && msg.timestamp - allMsg[idx - 1].timestamp < 60_000;

          return (
            <ChatEntry
              key={msg.id ?? idx}
              hideName={hideName}
              hideTimestamp={hideName === false ? false : hideTimestamp}
              entry={msg}
            />
          );
        })}
      </ul>

      <form className="lk-chat-form" onSubmit={handleSubmit}>
        <input
          className="lk-form-control lk-chat-form-input"
          disabled={isSending}
          ref={inputRef}
          type="text"
          placeholder="Ask about the lesson — no personal contacts"
          onInput={(ev) => ev.stopPropagation()}
          onKeyDown={(ev) => ev.stopPropagation()}
          onKeyUp={(ev) => ev.stopPropagation()}
        />
        <button type="submit" className="lk-button lk-chat-form-button" disabled={isSending}>
          Send
        </button>
      </form>
    </div>
  );
};

export default ModeratedLiveChat;
